package com.myaaptha.domain.health;import java.security.Principal;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/health") public class HealthController{private final HealthService service;private final HealthReportAnalyzer analyzer;public HealthController(HealthService s,HealthReportAnalyzer a){service=s;analyzer=a;}@GetMapping("/dashboard")public HealthService.Dashboard dashboard(Principal p){return service.dashboard(id(p));}@PostMapping("/reports")public HealthService.Report add(Principal p,@RequestBody HealthService.ReportInput input){return service.add(id(p),input);}@PostMapping(value="/reports/analyze",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public HealthService.Report analyze(Principal p,@RequestPart("file")MultipartFile file){return service.add(id(p),analyzer.analyze(file));}@DeleteMapping("/reports/{id}")public ResponseEntity<Void>delete(Principal p,@PathVariable Long id){service.delete(id(p),id);return ResponseEntity.noContent().build();}private Long id(Principal p){return Long.valueOf(p.getName());}}
